$tableFooter = "</table>";
$tableBody = "";
if ($result->num_rows > 0) {
  // output data of each row
  while($row = $result->fetch_assoc()) {
    $tableBody .= "<tr><td>" . $row["name"] . "</td><td>" . $row["value"] . "</td></tr>";
  }
} else {
  echo "0 results";
}
$conn->close();
echo $tableHeader . $tableBody . $tableFooter;
```
