How can we make the below code thread safe import java.util.\*;

public class Test {

 static HashMap map = new HashMap<>();

 static class Node {
 String val;
 ArrayList descendants; // this is track all the locked descendant nodes of a node
 Node parent;
 boolean isLocked;
 int uuid;

 Node(String val) {
 this.val = val;
 descendants = new ArrayList<>();
 isLocked = false;
 uuid = -1;
 parent = null;
 }

 public boolean lock(Node node, int uuid) {
 if (node.isLocked == true) {
 return false;
 }

 if (descendants.size() >= 1) {
 return false;
 }

 Node curr = node.parent;
 while (curr != null) {
 if (curr.isLocked == true) {
 return false;
 }
 curr = curr.parent;
 }

 // lock the node
 node.isLocked = true;
 node.uuid = uuid;

 curr = node.parent;
 while (curr != null) {
 curr.descendants.add(node);
 curr = curr.parent;
 }

 return true;

 }

 public boolean unlock(Node node, int uuid) {
 if (node.isLocked == false || node.uuid != uuid) {
 return false;
 }

 // unlock the node
 node.isLocked = false;
 node.uuid = -1;
 Node curr = node.parent;
 while (curr != null) {
 curr.descendants.remove(node);
 curr = curr.parent;
 }

 return true;
 }

 public boolean upgrade(Node node, int uuid) {
 if (node.isLocked == true) {
 return false;
 }

 boolean flag = false;
 for (Node curr : descendants) {
 if (curr.isLocked == true && curr.uuid != uuid) {
 return false;
 }
 if (curr.isLocked)
 flag = true;
 }

 if (!flag) {
 return false;
 }

 for (int i = 0; i < descendants.size(); i++) {
 unlock(descendants.get(i), uuid);
 }
 return lock(node, uuid);
 }

 }

 public static Node buildTree(String[] A, int no\_of\_children) {
 int curr = 0, n = A.length;
 Queue q = new LinkedList<>();
 Node root = new Node(A[curr]);
 map.put(A[curr], root);
 curr++;
 q.add(root);
 while (!q.isEmpty()) {
 Node front = q.poll();
 int i = 0;
 while (curr < n && i < no\_of\_children) {
 Node newNode = new Node(A[curr]);
 newNode.parent = front;
 q.add(newNode);
 map.put(A[curr], newNode);
 curr++;
 i++;
 }
 }
 return root;
 }

 public static void main(String[] args) {
 String[] arr = { "World", "Asia", "China", "India", "SouthAfrica", "Egypt" };
 int no\_of\_children = 2;
 Node root = buildTree(arr, no\_of\_children);
 Scanner sc = new Scanner(System.in);
 int queries = sc.nextInt();
 for (int i = 0; i < queries; i++) {
 int qn, uuid; // qn = query number
 String name;
 boolean ans = false;
 qn = sc.nextInt();
 name = sc.next();
 uuid = sc.nextInt();
 Node node = map.get(name);
 if (qn == 1) {
 ans = node.lock(node, uuid);
 } else if (qn == 2) {
 ans = node.unlock(node, uuid);
 } else {
 ans = node.upgrade(node, uuid);
 }

 System.out.println(ans);
 }

 }
}

