Consider this Java code: static int partition(int a[], int start, int end){

 int count = 0;

 int pivot = a[end]; //choose the last element in the array as the pivot

 int index= start - 1;

 for (int j = start; j < end; j++) //compare each element with pivot

 { 

 count++; 

 if (a[j] <= pivot) //if less, then, place before pivot’s

 { 

 count++;

 index++; //potential location, computed using index

 swap(a, index, j);

 }

 }

 swap(a, index+1, end);



 System.out.println("Number of comparisons: " + count);

 System.out.print("Partitioned array:");

 System.out.println(Arrays.toString(a)); 



 return index + 1; //final position of pivot is index+1

 }

