public function determineFrequency($now, $last, $frequency)
 {
 $charge = false;

 switch ($frequency) {
 case 1: // Monthly
 if ($now >= $last->addMonth()) {
 $future = $last->addDays(14);

 if ($now < $future) {
 $charge = true;
 }
 }
 break;
 case 2: // Quarterly
 if ($now >= $last->addMonths(3)) {
 $future = $last->addDays(14);

 if ($now < $future) {
 $charge = true;
 }
 }
 break;
 case 3: // Semiannually
 if ($now >= $last->addMonths(6)) {
 $future = $last->addDays(14);

