internal async Task PobierzAllDokumentsAsync(List downloadedFiles)
 {
 var (sprawdzResult, liczbaDokumentow) = await SprwadzAsync();
 if (sprawdzResult != EResponseResult.Success)
 return EResponseResult.Failed;
 if (liczbaDokumentow == 0)
 return EResponseResult.Success;

 var (filtrujResult, poswiadczenia, previousDokumentyPrzychodzace) = await FiltrujAsync();
 if (filtrujResult != EResponseResult.Success)
 return EResponseResult.Failed;

 for (int i = 0; i < liczbaDokumentow; i++)
 {
 var currentFullId = poswiadczenia.Posiwadczenia.FirstOrDefault().IdFullId;

 var poswiadczResult = await PoswiadczAsync(currentFullId);
 if (poswiadczResult != EResponseResult.Success)
 return EResponseResult.Failed;

 (filtrujResult, poswiadczenia, var dokumentyPrzychodzace) = await FiltrujAsync();
 if (filtrujResult != EResponseResult.Success)
 return EResponseResult.Failed;

 var newDokumentFullId = FindNewItemFullId(previousDokumentyPrzychodzace, dokumentyPrzychodzace);

 if(newDokumentFullId == null)
 return EResponseResult.Failed;

 var (pobierzResult, downloadFile) = await PobierzAsync(newDokumentFullId);
 if (pobierzResult != EResponseResult.Success)
 return EResponseResult.Failed;

 downloadedFiles.Add(downloadFile);

 previousDokumentyPrzychodzace = dokumentyPrzychodzace;
 }

 return EResponseResult.Success;
 }

