I use this function to save encrypted data to firebase, how would I then read this data from firebase?

import FirebaseFirestore
import CryptoKit

// Save encrypted data to Firebase Firestore
func saveEncryptedData(data: T, to collection: String, document: String, encryptionKey: SymmetricKey) {
 let db = Firestore.firestore()
 do {
 // Encode data as JSON
 let jsonData = try JSONEncoder().encode(data)

 // Encrypt data using AES
 let aes = AES.GCM.seal(jsonData, using: encryptionKey)

 // Convert encrypted data to base64 string
 let encryptedData = aes.combined!
 let encryptedDataString = encryptedData.base64EncodedString()

 // Save encrypted data to Firestore
 db.collection(collection).document(document).setData([
 "data": encryptedDataString
 ]) { (error) in
 if let error = error {
 print("Error saving encrypted data to Firestore: \(error)")
 } else {
 print("Encrypted data saved to Firestore successfully!")
 }
 }
 } catch {
 print("Error encoding data: \(error)")
 }
}

