 if (typeof attr !== "function") {
 \_props[key] = attributes[key];
 continue;
 } else \_redo.push(key);
 }
 children.forEach((child) => {
 if (child === false) return;
 if (typeof child === "function") child(\_element);
 else \_element.appendChild(child);
 });
 if (\_props["dataset"]) {
