 addHook(\_idx, (newVal) => {
 \_element.style[style] = newVal;
 });
 \_element.style[style] = \_val;
 } else {
 \_element.style[style] = \_props.style[style];
 }
 }
 }
 \_redo.forEach((key) => {
 let attr = attributes[key];
 if (states.includes(attr)) {
 let \_idx = states.indexOf(attr);
 attr = states[\_idx]();
 addHook(\_idx, (newVal) => {
 \_element[key] = newVal;
 });
 }
 \_element[key] = attr;
 });
 return \_element;
 }

 function addStyleSheet(path) {
 let prefix = INCL\_DIR ? INCL\_DIR : "../../incl";
 let href = `${prefix}/components/${path}`;
 const styleSheet = Renderer.createElement("link", {
 rel: "stylesheet",
 type: "text/css",
 href: href,
 });
 document.querySelector("head").appendChild(styleSheet);
 }

 const addHook = (idx, hook) => {
 if (hooks[idx]) {
 hooks[idx].push(hook);
 } else {
 hooks[idx] = [hook];
 }
 };

 const useState = (defaultValue) => {
 let callback = typeof defaultValue == "function" ? defaultValue : null;
 let \_value = defaultValue;
 const \_idx = idx++;

 const getState = () => {
 return typeof callback === "function" ? callback() : \_value;
 };

 const setState = (newValue) => {
 \_value = newValue;
 if (hooks[\_idx] !== undefined) {
 hooks[\_idx].forEach((hook) => {
 hook(\_value);
 });
 }
 checkEffects(\_idx);
 };

 states[\_idx] = getState;

 return [getState, setState];
 };

 const useEffect = (callback, ...watches) => {
 let \_idx = idx++;

 effects[\_idx] = [];

 watches.forEach((watch) => {
 let \_oldValue = watch();
 $(document).ready(() => {
 callback(\_oldValue, \_oldValue);
 });
 effects[\_idx].push(() => {
 let newVal = watch();
 if (typeof \_oldValue === "object" && typeof newVal === "object") {
 if (JSON.stringify(\_oldValue) !== JSON.stringify(newVal)) {
 callback(newVal, \_oldValue);
 \_oldValue = newVal;
 }
 } else {
 if (\_oldValue !== newVal) {
 callback(newVal, \_oldValue);
 \_oldValue = newVal;
 }
 }
 });
 });
 };

 function checkEffects(\_idx) {
 if (\_rendering) return;
 \_rendering = true;
 effects.forEach((effect) => {
 effect.forEach((watch) => {
 watch();
 });
 });
 expressions.forEach((expression) => {
 expression.setRes(expression.res());
 });
 \_rendering = false;
 }

 function useExpression(expression, result, onFalse) {
 if (typeof expression !== "function") {
 console.warn("Expression must be of type function");
 return;
 }

 let \_idx = idx++;
 let \_parent = null;

 const [res, setRes] = useState(expression);
 const [prop, setProp] = useState(result);

 expressions[\_idx] = {
 res: res,
 setRes: setRes,
 };

