  void printTraits() const override { cout << "Breed: " << breed << ", Size: " << size << ", Temperament: " << temperament << endl; }
  void setBreed(string breed) { this->breed = breed; }
  void setSize(string size) { this->size = size; }
  void setTemperament(string temperament) { this->temperament = temperament; }
