class Example(dotdict):
 def \_\_init\_\_(self, \*args, \*\*kwargs):
 assert len(args) <= 1
 super().\_\_init\_\_()

 if len(args):
 assert len(args) == 1
 self.update(args[0])

 self.update(\*\*kwargs)

 def copy(self, \*\*kwargs):
 the\_copy = Example(\*\*{\*\*dict(self), \*\*kwargs})

 return the\_copy

 def without(self, \*keys):
 keys = set(keys)
 return Example({k: v for k, v in self.items() if k not in keys})

 def demos\_at(self, fn):
 def at(d):
 try:
 return fn(d).without('augmented')
 except:
 return {}

 demos = [d.copy(\*\*at(d)) for d in self.demos]
 return self.copy(demos=demos)
